import { z } from 'zod';

/** A paired device (phone or agent); the relay assigns it at enrolment. */
export const DeviceId = z.uuid();

/** Sender-generated envelope id; `(from, id)` is the receiver's dedup key (D14). */
export const EnvelopeId = z.uuidv7();

/** A permission request or question, generated by the agent when the hook fires (D7). */
export const RequestId = z.uuid();

/** An agent session id (Claude Code `session_id`), opaque to the protocol. */
export const SessionId = z.string().min(1).max(128);

/** An opaque, URL-safe identifier chosen by the agent (for example a repository id). */
export const OpaqueId = z.string().regex(/^[A-Za-z0-9_-]{1,64}$/);

/** A coding agent kind, such as `claude-code` (D12: adapter boundary from day one). */
export const AgentId = z.string().regex(/^[a-z][a-z0-9-]{0,31}$/);

/** Lower-case hex SHA-256 digest. */
export const Sha256Hex = z.string().regex(/^[0-9a-f]{64}$/);

/** Unix epoch milliseconds. */
export const EpochMs = z.int().nonnegative();
